{"path": "D:\cncodetest\snake-game\server.js", "content": "const express = require('express');
const path = require('path');
const Database = require('better-sqlite3');

const app = express();
const PORT = 3000;

// 解析 JSON 请求体
app.use(express.json());

// 提供静态文件
app.use(express.static(path.join(__dirname, 'public')));

// 初始化 SQLite 数据库
const db = new Database('snake.db');
db.pragma('journal_mode = WAL');

// 创建高分榜表
db.exec(`
  CREATE TABLE IF NOT EXISTS scores (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    player_name TEXT NOT NULL,
    score INTEGER NOT NULL,
    snake_length INTEGER NOT NULL,
    difficulty TEXT DEFAULT 'normal',
    achieved_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

// 插入新分数
app.post('/api/scores', (req, res) => {
  const { player_name, score, snake_length, difficulty } = req.body;
  if (!player_name || score === undefined) {
    return res.status(400).json({ error: '缺少必要参数' });
  }
  try {
    const stmt = db.prepare(
      'INSERT INTO scores (player_name, score, snake_length, difficulty) VALUES (?, ?, ?, ?)'
    );
    const result = stmt.run(player_name, score, snake_length, difficulty || 'normal');
    res.json({ id: result.lastInsertRowid, message: '分数已保存！' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 获取高分榜（前10名）
app.get('/api/scores', (req, res) => {
  try {
    const rows = db.prepare(
      'SELECT * FROM scores ORDER BY score DESC, snake_length DESC LIMIT 10'
    ).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 获取个人最高分
app.get('/api/scores/:name', (req, res) => {
  try {
    const row = db.prepare(
      'SELECT * FROM scores WHERE player_name = ? ORDER BY score DESC LIMIT 1'
    ).get(req.params.name);
    res.json(row || { score: 0 });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(PORT, () => {
  console.log(`🐍 贪吃蛇游戏运行在 http://localhost:${PORT}`);
});
"}

