  border-radius: 10px;
  font-size: 1.05rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s;
  margin: 8px 5px;
  background: linear-gradient(135deg, #00d2ff, #3a7bd5);
  color: #fff;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 210, 255, 0.35);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.15);
  color: #ddd;
}

