  height: 400px;
  max-width: 100%;
}

.controls {
  margin-top: 12px;
  display: flex;
  justify-content: center;
  gap: 10px;
}

.mobile-controls {
  display: none;
  margin-top: 15px;
  text-align: center;
}

.mobile-controls .dir-btn {
  width: 60px;
  height: 60px;
  margin: 3px;
  border: none;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.12);
