    height: 300px;
  }
}

#gameOverScreen p {
  font-size: 1.2rem;
  margin: 10px 0;
}

/* 高分榜表格 */
#scoresTable {
  width: 100%;
  border-collapse: collapse;
  margin: 15px 0;
}

#scoresTable th,
#scoresTable td {
  padding: 8px 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.85rem;
}

#scoresTable th {
  color: #ffd700;
  font-weight: 600;
}

#scoresTable tr:hover td {
  background: rgba(255, 255, 255, 0.05);
}
